import { NextResponse } from "next/server";
import { createRouteClient } from "@/lib/supabase-server";
import { finalizeSignIn } from "@/lib/auth-finalize";
import { isOAuthProvider, safeNextPath } from "@/lib/auth-config";
import { clientIp } from "@/lib/turnstile";
import { setActiveOrgCookie } from "@/lib/auth-session";

export const dynamic = "force-dynamic";

/**
 * PKCE callback for Google, Microsoft, email confirmation, password recovery
 * and magic links started from this server.
 *
 * Links generated by the Supabase admin API (inviteUserByEmail) use the
 * implicit flow and carry tokens in the URL fragment, which never reaches the
 * server. Those are forwarded to /auth/complete; browsers keep the fragment
 * across a redirect whose Location has none.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const origin = url.origin;
  const next = safeNextPath(url.searchParams.get("next"));
  const providerParam = url.searchParams.get("provider");
  const code = url.searchParams.get("code");

  const loginError = (reason: string) =>
    NextResponse.redirect(new URL(`/login?error=${encodeURIComponent(reason)}`, origin));

  const providerError = url.searchParams.get("error_description") || url.searchParams.get("error");
  if (providerError) {
    console.error("OAuth callback error:", providerError);
    return loginError(/expired|invalid/i.test(providerError) ? "link_expired" : "session_error");
  }

  if (!code) {
    return NextResponse.redirect(new URL(`/auth/complete?next=${encodeURIComponent(next)}`, origin));
  }

  const supabase = createRouteClient();
  const { data, error } = await supabase.auth.exchangeCodeForSession(code);

  if (error || !data.user) {
    console.error("exchangeCodeForSession:", error?.message);
    return loginError(/verifier/i.test(error?.message || "") ? "link_expired" : "session_error");
  }

  const result = await finalizeSignIn(data.user, {
    provider: isOAuthProvider(providerParam) ? providerParam : undefined,
    ip: clientIp(request),
  });

  if (result.status === "denied") {
    await supabase.auth.signOut();
    return loginError(result.reason);
  }

  if (result.status === "pending") {
    return NextResponse.redirect(new URL("/auth/pending", origin));
  }

  return setActiveOrgCookie(NextResponse.redirect(new URL(next, origin)), result.organizationId);
}
